  INSERT INTO subcontract_request_local (id, legacy_id, company_id, trial_id, trial_service_id, service_id, posted_by_user_id, preferred_consultant_id, service_name, description, location, estimated_rate, start_date, end_date, cancelled_date, status, invited_company_ids, invited_user_ids, viewed_by_user_ids, preferred_consultants_map, created_at, updated_at, is_sample, created_by_id, created_by)
  VALUES (COALESCE(NEW.id, gen_random_uuid()::text), NEW.legacy_id, NEW.company_id, NEW.trial_id, NEW.trial_service_id, NEW.service_id, NEW.posted_by_user_id, NEW.preferred_consultant_id, NEW.service_name, NEW.description, NEW.location, NEW.estimated_rate, NEW.start_date, NEW.end_date, NEW.cancelled_date, NEW.status, NEW.invited_company_ids, NEW.invited_user_ids, NEW.viewed_by_user_ids, NEW.preferred_consultants_map, NEW.created_at, NEW.updated_at, NEW.is_sample, NEW.created_by_id, NEW.created_by);
  INSERT INTO local_writes (entity, operation, row_id, payload)
  VALUES ('subcontract_request', 'insert', NEW.id, to_jsonb(NEW));
  PERFORM pg_notify('local_write', 'subcontract_request');
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION subcontract_request_update() RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO subcontract_request_local (id, legacy_id, company_id, trial_id, trial_service_id, service_id, posted_by_user_id, preferred_consultant_id, service_name, description, location, estimated_rate, start_date, end_date, cancelled_date, status, invited_company_ids, invited_user_ids, viewed_by_user_ids, preferred_consultants_map, created_at, updated_at, is_sample, created_by_id, created_by)
  VALUES (NEW.id, NEW.legacy_id, NEW.company_id, NEW.trial_id, NEW.trial_service_id, NEW.service_id, NEW.posted_by_user_id, NEW.preferred_consultant_id, NEW.service_name, NEW.description, NEW.location, NEW.estimated_rate, NEW.start_date, NEW.end_date, NEW.cancelled_date, NEW.status, NEW.invited_company_ids, NEW.invited_user_ids, NEW.viewed_by_user_ids, NEW.preferred_consultants_map, NEW.created_at, NEW.updated_at, NEW.is_sample, NEW.created_by_id, NEW.created_by)
  ON CONFLICT (id) DO UPDATE SET
    legacy_id = EXCLUDED.legacy_id,
    company_id = EXCLUDED.company_id,
    trial_id = EXCLUDED.trial_id,
    trial_service_id = EXCLUDED.trial_service_id,
    service_id = EXCLUDED.service_id,
    posted_by_user_id = EXCLUDED.posted_by_user_id,
    preferred_consultant_id = EXCLUDED.preferred_consultant_id,
    service_name = EXCLUDED.service_name,
    description = EXCLUDED.description,
    location = EXCLUDED.location,
    estimated_rate = EXCLUDED.estimated_rate,
    start_date = EXCLUDED.start_date,
    end_date = EXCLUDED.end_date,
    cancelled_date = EXCLUDED.cancelled_date,
    status = EXCLUDED.status,
    invited_company_ids = EXCLUDED.invited_company_ids,
    invited_user_ids = EXCLUDED.invited_user_ids,
    viewed_by_user_ids = EXCLUDED.viewed_by_user_ids,
    preferred_consultants_map = EXCLUDED.preferred_consultants_map,
    updated_at = EXCLUDED.updated_at,
    is_sample = EXCLUDED.is_sample,
    created_by_id = EXCLUDED.created_by_id,
    created_by = EXCLUDED.created_by,
    is_deleted = false;
  INSERT INTO local_writes (entity, operation, row_id, payload)
  VALUES ('subcontract_request', 'update', NEW.id, to_jsonb(NEW));
  PERFORM pg_notify('local_write', 'subcontract_request');
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION subcontract_request_delete() RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO subcontract_request_local (id, is_deleted) VALUES (OLD.id, true)
  ON CONFLICT (id) DO UPDATE SET is_deleted = true;
  INSERT INTO local_writes (entity, operation, row_id, payload)
  VALUES ('subcontract_request', 'delete', OLD.id, NULL);
  PERFORM pg_notify('local_write', 'subcontract_request');
  RETURN OLD;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS subcontract_request_insert_trg ON subcontract_request;
DROP TRIGGER IF EXISTS subcontract_request_update_trg ON subcontract_request;
DROP TRIGGER IF EXISTS subcontract_request_delete_trg ON subcontract_request;
CREATE TRIGGER subcontract_request_insert_trg INSTEAD OF INSERT ON subcontract_request
  FOR EACH ROW EXECUTE FUNCTION subcontract_request_insert();
CREATE TRIGGER subcontract_request_update_trg INSTEAD OF UPDATE ON subcontract_request
  FOR EACH ROW EXECUTE FUNCTION subcontract_request_update();
CREATE TRIGGER subcontract_request_delete_trg INSTEAD OF DELETE ON subcontract_request
  FOR EACH ROW EXECUTE FUNCTION subcontract_request_delete();

-- ── subcontract_assignment ──────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS subcontract_assignment_synced (
  id                           TEXT,
  legacy_id                    TEXT,
  hiring_company_id            TEXT,
  subcontractor_company_id     TEXT,
  trial_id                     TEXT,
  trial_service_id             TEXT,
  request_id                   TEXT,
  response_id                  TEXT,
  consultant_id                TEXT,
  mapped_service_id            TEXT,
  consultant_first_name        TEXT,
  consultant_last_name         TEXT,
  subcontractor_job_number     TEXT,
  agreed_rate                  NUMERIC,
  estimated_total              NUMERIC,
  agreement_pdf_url            TEXT,
  start_date                   TEXT,
  end_date                     TEXT,
  status                       TEXT,
  subcontractor_accepted_at    TEXT,
  hiring_accepted_at           TEXT,
  cancelled_by                 TEXT,
  created_at                   TEXT,
  updated_at                   TEXT,
  is_sample                    BOOLEAN,
  created_by_id                TEXT,
  created_by                   TEXT
);

CREATE TABLE IF NOT EXISTS subcontract_assignment_local (
  id                           TEXT,
  legacy_id                    TEXT,
  hiring_company_id            TEXT,
  subcontractor_company_id     TEXT,
  trial_id                     TEXT,
  trial_service_id             TEXT,
  request_id                   TEXT,
  response_id                  TEXT,
  consultant_id                TEXT,
  mapped_service_id            TEXT,
  consultant_first_name        TEXT,
  consultant_last_name         TEXT,
  subcontractor_job_number     TEXT,
  agreed_rate                  NUMERIC,
  estimated_total              NUMERIC,
  agreement_pdf_url            TEXT,
  start_date                   TEXT,
  end_date                     TEXT,
  status                       TEXT,
  subcontractor_accepted_at    TEXT,
  hiring_accepted_at           TEXT,
  cancelled_by                 TEXT,
  created_at                   TEXT,
  updated_at                   TEXT,
  is_sample                    BOOLEAN,
  created_by_id                TEXT,
  created_by                   TEXT,
  is_deleted                   BOOLEAN NOT NULL DEFAULT false
);

CREATE OR REPLACE VIEW subcontract_assignment AS
  SELECT s.* FROM subcontract_assignment_synced s
  WHERE NOT EXISTS (SELECT 1 FROM subcontract_assignment_local l WHERE l.id = s.id)
  UNION ALL
  SELECT l.id, l.legacy_id, l.hiring_company_id, l.subcontractor_company_id, l.trial_id, l.trial_service_id, l.request_id, l.response_id, l.consultant_id, l.mapped_service_id, l.consultant_first_name, l.consultant_last_name, l.subcontractor_job_number, l.agreed_rate, l.estimated_total, l.agreement_pdf_url, l.start_date, l.end_date, l.status, l.subcontractor_accepted_at, l.hiring_accepted_at, l.cancelled_by, l.created_at, l.updated_at, l.is_sample, l.created_by_id, l.created_by
  FROM subcontract_assignment_local l
  WHERE NOT l.is_deleted;

